package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64 // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsLabel string = "                    " // PIC X(20) len=20 = SPACES
var WsACount int64 = 0 // PIC 99 len=2 = 0
var WsTotalA int64 = 0 // PIC 999 len=3 = 0
var WsCount int64 = 0 // PIC 999 len=3 = 0

var PartRecData PartRec
var PartFileData []PartRec
var PartFileIdx int

func InputDone() bool {
	return WsEofFlag == "Y"
}

func parseSerial(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	n, err := strconv.ParseInt(t, 10, 64)
	if err != nil {
		return 0
	}
	return n
}

func openPartFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	PartFileData = nil
	PartFileIdx = 0
	if len(data) == 0 {
		return
	}
	s := string(data)
	parts := strings.Split(s, "\n")
	if strings.HasSuffix(s, "\n") {
		parts = parts[:len(parts)-1]
	}
	for _, line := range parts {
		if strings.HasSuffix(line, "\r") {
			line = strings.TrimSuffix(line, "\r")
		}
		var recStr string
		if len(line) < 15 {
			recStr = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			recStr = line[:15]
		} else {
			recStr = line
		}
		var r PartRec
		r.LbPart = recStr[0:8]
		r.LbRegion = recStr[8:11]
		r.LbSerial = parseSerial(recStr[11:15])
		PartFileData = append(PartFileData, r)
	}
}

func MainPara() {
	openPartFile()
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	// CLOSE PART-FILE (no-op)
	SummaryPara()
}

func ReadPara() {
	if PartFileIdx < len(PartFileData) {
		PartRecData = PartFileData[PartFileIdx]
		PartFileIdx++
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	cnt := int64(strings.Count(PartRecData.LbPart, "A"))
	WsACount = (WsACount + cnt) % 100

	regionEff := PartRecData.LbRegion
	if idx := strings.IndexByte(regionEff, ' '); idx >= 0 {
		regionEff = regionEff[:idx]
	}
	partEff := PartRecData.LbPart
	if idx := strings.IndexByte(partEff, ' '); idx >= 0 {
		partEff = partEff[:idx]
	}
	serialEff := fmt.Sprintf("%04d", PartRecData.LbSerial)

	buf := make([]byte, 20)
	for i := range buf {
		buf[i] = ' '
	}
	pos := 0
	putStr := func(s string) {
		for i := 0; i < len(s); i++ {
			if pos < 20 {
				buf[pos] = s[i]
				pos++
			} else {
				break
			}
		}
	}
	putStr(regionEff)
	putStr("-")
	putStr(partEff)
	putStr("-")
	putStr(serialEff)
	WsLabel = string(buf)

	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000
	fmt.Printf("%s A=%02d\n", WsLabel, WsACount%100)
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("LABELS: %03d A-TOTAL: %03d\n", WsCount%1000, WsTotalA%1000)
}

func main() {
	MainPara()
}
